<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import {memberRpc} from './member-service.js'
const groups=ref([]),matches=ref([]),chosenGroups=ref([]),chosenUsers=ref([]),search=ref(''),subject=ref(''),body=ref(''),preview=ref([]),history=ref([]),busy=ref(false),message=ref(''),confirmed=ref(false),requestId=ref(null),previewFingerprint=ref('')
const fingerprint=()=>JSON.stringify([chosenGroups.value.slice().sort(),chosenUsers.value.slice().sort(),subject.value,body.value])
async function run(fn){if(busy.value)return;busy.value=true;message.value='';try{await fn()}catch(e){message.value=e.message}finally{busy.value=false}}
async function loadHistory(){history.value=await memberRpc('member_mail_history')}
async function find(){await run(async()=>{matches.value=await memberRpc('pms_find_members',{p_search:search.value})})}
async function review(){await run(async()=>{preview.value=await memberRpc('member_mail_preview',{p_groups:chosenGroups.value,p_users:chosenUsers.value});previewFingerprint.value=fingerprint();confirmed.value=false;requestId.value=crypto.randomUUID();message.value=preview.value.length+'명의 수신자와 본문을 확인해 주세요.'})}
async function send(){if(!confirmed.value)return;await run(async()=>{if(fingerprint()!==previewFingerprint.value)throw Error('대상이나 본문이 변경되었습니다. 수신자를 다시 확인해 주세요.');await memberRpc('member_mail_send',{p_request:requestId.value,p_groups:chosenGroups.value,p_users:chosenUsers.value,p_subject:subject.value,p_body:body.value,p_expected:preview.value.map(x=>x.email)});confirmed.value=false;preview.value=[];message.value='발송을 요청했습니다. 아래 이력에서 수신자별 결과를 확인해 주세요.';await loadHistory()})}
const states={queued:'발송 대기',sending:'발송 중',sent:'발송 요청 완료',failed:'실패',unknown:'결과 확인 필요',cancelled:'취소'}
onMounted(()=>run(async()=>{groups.value=await memberRpc('pms_groups_list');await loadHistory()}));onUnmounted(()=>{preview.value=[];matches.value=[];body.value=''})
</script><template><main class="member-page"><h1>메일 발송</h1><p>표시명: 피엠오피스(nam@pmoffice.co.kr) · 회신: nam@pmoffice.co.kr</p><p role="status" aria-live="polite">{{message}}</p><div class="member-columns"><section class="member-panel"><h2>수신 대상</h2><h3>그룹 선택</h3><label class="member-check" v-for="g in groups.filter(g=>g.active)" :key="g.id"><input type="checkbox" v-model="chosenGroups" :value="g.id"><span>{{g.name}}</span></label><h3>회원 선택</h3><form @submit.prevent="find" class="member-form"><label>회원 검색<input v-model="search" required minlength="2" maxlength="120" placeholder="이메일, 이름, 회사명"></label><button :disabled="busy">회원 찾기</button></form><label class="member-check" v-for="u in matches" :key="u.id"><input type="checkbox" v-model="chosenUsers" :value="u.id"><span>{{u.display_name}} · {{u.email}} · {{u.company}}</span></label><p>선택한 개인 회원 {{chosenUsers.length}}명 · 그룹 {{chosenGroups.length}}개</p><button @click="chosenUsers=[];chosenGroups=[];preview=[]">대상 선택 지우기</button></section>
<section class="member-panel"><h2>메일 작성</h2><form @submit.prevent="review" class="member-form"><label>제목<input v-model="subject" required maxlength="200"></label><label>본문<textarea v-model="body" rows="12" required maxlength="50000"></textarea></label><button :disabled="busy||!chosenGroups.length&&!chosenUsers.length">수신자·본문 확인</button></form><section v-if="preview.length"><h3>최종 수신자 {{preview.length}}명</h3><ul><li v-for="u in preview" :key="u.id">{{u.display_name}} · {{u.email}}</li></ul><p class="member-note">중복 주소는 한 번만 발송하며, 수신자별로 개별 메일을 보냅니다.</p><label class="member-check"><input v-model="confirmed" type="checkbox"><span>위 수신자와 제목·본문으로 발송</span></label><button @click="send" :disabled="busy||!confirmed">메일 발송</button></section></section></div>
<h2>발송 이력</h2><button @click="run(loadHistory)" :disabled="busy">결과 새로고침</button><div class="member-history"><table><thead><tr><th>수신자</th><th>제목</th><th>상태</th><th>처리 시각</th></tr></thead><tbody><tr v-for="m in history" :key="m.id"><td>{{m.recipient}}</td><td>{{m.subject}}</td><td>{{states[m.state]}}<span v-if="m.error"> · {{m.error}}</span></td><td>{{new Date(m.updated_at).toLocaleString('ko-KR')}}</td></tr></tbody></table></div><p>결과 확인 필요 상태는 자동 재발송하지 않습니다. 실제 받은편지함 도착은 발송 요청 완료와 구분합니다.</p></main></template>
